"h": "Adjusted (corrected) age",
"body": [
"Slides 10-11: adjusted age is the age a child would be if born on the **due date**. Used mainly for **premature infants** (speech, language, feeding, early communication). Without it, a preterm infant compared to same-age peers may **appear delayed** when development is appropriate for the time they have had; using it helps **avoid over-identifying delays**.",
"**Adjusted age = chronological age − weeks (or months) premature.** Her example: DOB January 1, 2026; due date March 1, 2026; born 8 weeks early. Assessed September 1, 2026: CA 8 months; prematurity 2 months (8 weeks); **adjusted age 6 months**."
],
